",":root {
 --app-primary-bg: var(--now-color--primary-1, 0,128,163);
 --app-surface-bg: var(--now-color_surface--brand-1, 229,242,246);
 --app-neutral-bg: var(--now-color--neutral-1, 245,246,247);
 --app-neutral-border: var(--now-color--neutral-10, 79,92,98);
 --app-text-primary: var(--now-color--neutral-18, 22,27,28);
 --app-text-secondary: var(--now-color--neutral-12, 55,68,74);
}

* {
 margin: 0;
 padding: 0;
 box-sizing: border-box;
}

body {
 font-family: var(--now-font-family, "Source Sans Pro", Arial, sans-serif);
 background-color: rgb(var(--app-neutral-bg));
 color: rgb(var(--app-text-primary));
 min-height: 100vh;
}

.app-container {
 max-width: 1200px;
 margin: 0 auto;
 padding: 24px;
}

/* Header */
.app-header {
 background-color: rgb(var(--app-primary-bg));
 color: rgb(var(--now-color--neutral-0, 255,255,255));
 padding: 20px 24px;
 border-radius: var(--now-form-control--border-radius, 6px);
 margin-bottom: 24px;
 display: flex;
 align-items: center;
 justify-content: space-between;
}

.app-header-title {
 display: flex;
 flex-direction: column;
}

.app-header-actions {
 display: flex;
 gap: 12px;
 align-items: center;
}

/* View Container */
.view-container {
 background-color: rgb(var(--now-color--neutral-0, 255,255,255));
 border-radius: var(--now-form-control--border-radius, 6px);
 box-shadow: 0 1px 4px rgba(0, 0, 0, 0.08);
 overflow: hidden;
}

/* Test Form */
.test-form-container {
 margin-top: 8px;
}

.test-form-inner {
 display: flex;
 flex-direction: column;
 gap: 16px;
}

.test-form-description {
 font-size: 14px;
 color: rgb(var(--app-text-secondary));
 line-height: 1.5;
}

.test-form-field {
 margin-top: 4px;
}

.test-form-actions {
 display: flex;
 gap: 12px;
 margin-top: 8px;
}

/* Loader */
.test-loader-container {
 display: flex;
 justify-content: center;
 align-items: center;
 min-height: 300px;
 background-color: rgb(var(--now-color--neutral-0, 255,255,255));
 border-radius: var(--now-form-control--border-radius, 6px);
 box-shadow: 0 1px 4px rgba(0, 0, 0, 0.08);
}

/* Test Results */
.test-results {
 display: flex;
 flex-direction: column;
 gap: 20px;
}

.results-url {
 font-size: 14px;
 color: rgb(var(--app-text-secondary));
 word-break: break-all;
}

/* Summary Section */
.summary-section {
 display: flex;
 flex-direction: column;
 gap: 16px;
}

.summary-badges {
 display: flex;
 gap: 24px;
 flex-wrap: wrap;
}

.summary-badge-item {
 display: flex;
 align-items: center;
 gap: 8px;
}

.summary-label {
 font-size: 14px;
 font-weight: 600;
 color: rgb(var(--app-text-primary));
}

/* Results Sections */
.results-section {
 display: flex;
 flex-direction: column;
 gap: 8px;
}

.results-actions {
 display: flex;
 gap: 12px;
 margin-top: 8px;
}

/* Create Form */
.create-form-wrapper {
 padding: 24px;
}

.create-form-header {
 display: flex;
 align-items: center;
 justify-content: space-between;
 margin-bottom: 20px;
 padding-bottom: 16px;
 border-bottom: 1px solid rgb(var(--now-card-divider--color, 207,213,215));
}

.create-form-header h2 {
 font-size: 18px;
 font-weight: 600;
 color: rgb(var(--app-text-primary));
 margin: 0;
}

/* Status Badges */
.status-badge {
 display: inline-flex;
 align-items: center;
 padding: 2px 10px;
 border-radius: 12px;
 font-size: 12px;
 font-weight: 600;
 text-transform: uppercase;
 letter-spacing: 0.5px;
}

.status-badge--pending {
 background-color: rgb(var(--now-color_surface--brand-1, 229,242,246));
 color: rgb(var(--app-primary-bg));
}

.status-badge--completed {
 background-color: rgba(51, 131, 11, 0.1);
 color: rgb(var(--now-actionable--primary-positive--background-color, 51,131,11));
}

.status-badge--failed {
 background-color: rgba(228, 35, 56, 0.1);
 color: rgb(var(--now-actionable--primary-negative--background-color, 228,35,56));
}

.status-badge--in_progress {
 background-color: rgba(0, 121, 204, 0.1);
 color: rgb(var(--now-card_sidebar--primary_info--background-color, 0,121,204));
}

/* Empty State */
.empty-state {
 text-align: center;
 padding: 48px 24px;
 color: rgb(var(--app-text-secondary));
}

.empty-state h3 {
 font-size: 18px;
 margin: 0 0 8px 0;
}

.empty-state p {
 font-size: 14px;
 margin: 0 0 20px 0;
}
","export default function insertStyle(css, tagName = "style") {
 if (!css || typeof window === "undefined")
 return;
 if (tagName === "style") {
 const style = document.createElement("style");
 style.setAttribute("type", "text/css");
 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
 }
 return css;
}","import React from "react";
import ReactDOM from "react-dom/client";
import App from "./app";

ReactDOM.createRoot(document.getElementById("root")!).render(<App />);
","import React, { useState } from "react";
import "./app.css";

export default function App() {
 const [url, setUrl] = useState("");
 const [submitted, setSubmitted] = useState(false);

 const handleSubmit = () => {
 if (!url) return;
 setSubmitted(true);
 };

 return (
 <div className="app-container">
 <div className="app-header">
 <div className="app-header-title">
 <h1 style={{ color: "white", fontSize: "22px" }}>Accessibility Tester</h1>
 <p style={{ color: "rgba(255,255,255,0.9)", fontSize: "14px", marginTop: "4px" }}>
 Test websites for accessibility compliance
 </p>
 </div>
 </div>

 <div className="view-container" style={{ padding: "24px" }}>
 {submitted ? (
 <div>
 <h2 style={{ marginBottom: "12px" }}>URL Submitted!</h2>
 <p style={{ marginBottom: "16px" }}>
 The URL <strong>{url}</strong> has been submitted for testing.
 </p>
 <button
 onClick={() => { setSubmitted(false); setUrl(""); }}
 style={{
 padding: "8px 16px",
 backgroundColor: "rgb(0,128,163)",
 color: "white",
 border: "none",
 borderRadius: "4px",
 cursor: "pointer",
 fontSize: "14px",
 }}
 >
 Test Another URL
 </button>
 </div>
 ) : (
 <div>
 <h2 style={{ marginBottom: "12px" }}>Test a Website</h2>
 <p style={{ marginBottom: "16px", color: "#374a4e" }}>
 Enter a URL below to run accessibility checks.
 </p>
 <div style={{ marginBottom: "16px" }}>
 <label
 htmlFor="site-url"
 style={{ display: "block", marginBottom: "6px", fontWeight: 600 }}
 >
 Site URL
 </label>
 <input
 id="site-url"
 type="url"
 placeholder="https://example.com"
 value={url}
 onChange={(e) => setUrl(e.target.value)}
 style={{
 width: "100%",
 padding: "8px 12px",
 border: "1px solid #cfd5d7",
 borderRadius: "4px",
 fontSize: "14px",
 boxSizing: "border-box",
 }}
 />
 </div>
 <button
 onClick={handleSubmit}
 disabled={!url}
 style={{
 padding: "8px 24px",
 backgroundColor: url ? "rgb(0,128,163)" : "#ccc",
 color: "white",
 border: "none",
 borderRadius: "4px",
 cursor: url ? "pointer" : "not-allowed",
 fontSize: "14px",
 fontWeight: 600,
 }}
 >
 Submit
 </button>
 </div>
 )}
 </div>
 </div>
 );
}
